event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_062d2f1d14fc8e82006ab5a00b5ed087d2b9bc4f67cee402e5","logprobs":[],"output_index":0,"sequence_number":350,"text":"{\"name\":\"Classic Margherita Pizza\",\"ingredients\":[\"2 cups all-purpose flour\",\"1 teaspoon salt\",\"1 teaspoon sugar\",\"1 packet (2 1/4 teaspoons) active dry yeast\",\"3/4 cup warm water (110°F)\",\"1 tablespoon olive oil\",\"1 cup crushed tomatoes\",\"8 ounces fresh mozzarella cheese, sliced\",\"Fresh basil leaves\",\"Salt and pepper to taste\",\"Olive oil for drizzling\"],\"steps\":[\"In a small bowl, combine warm water, sugar, and yeast. Let it sit for 5-10 minutes until foamy.\",\"In a large mixing bowl, combine flour and salt. Make a well in the center, and add the yeast mixture and olive oil.\",\"Mix until a dough forms, then knead on a floured surface for about 5-7 minutes until smooth.\",\"Place the dough in a lightly oiled bowl, cover with a cloth, and let it rise in a warm place for about 1 hour or until doubled in size.\",\"Preheat your oven to 475°F (245°C). If using a pizza stone, place it in the oven while preheating.\",\"Roll out the dough on a floured surface to your desired thickness and shape.\",\"Transfer the dough to a piece of parchment paper or a floured pizza peel if using a stone.\",\"Spread the crushed tomatoes evenly over the dough, leaving a small border around the edges. Season with salt and pepper.\",\"Lay the fresh mozzarella slices evenly on top of the tomatoes.\",\"Bake in the preheated oven for 10-12 minutes, or until the crust is golden and the cheese is bubbly.\",\"Once out of the oven, add fresh basil leaves and drizzle with olive oil before slicing and serving.\"]}"}

